member.summary:
Usage is like this:

using(AppConfig.Change(tempFileName))
{
    the app.config in tempFileName is used
}

If you want to change the used app.config for the whole runtime of your application, simply put 
AppConfig.Change(tempFileName) without the using somewhere at the start of your application.

( http://stackoverflow.com/questions/6150644/change-default-app-config-at-runtime )

member.example:
    Get a list of nodes belonging to specific components, using  scope.
    
        var app = IoC.Get<IApplication>();
        ISimNode node1 = app.World.FindComponent("node1").RootNode;
        ISimNode node2 = app.World.FindComponent("node2").RootNode;

        List<NodeListEntry> entries = new List<NodeListEntry>
        {
            new NodeListEntry(node1, NodeEntryScope.Component, NodeEntryType.Include),
            new NodeListEntry(node2, NodeEntryScope.Component, NodeEntryType.Include),
        };

        var resultNodes = IoC.Get<INodeEntryListHelper>().FilterNodes(entries);

    Get a list of all nodes in the world using  scope.
    From that list, exclude whole component and a specific node from another component.
    
        var app = IoC.Get<IApplication>();
        ISimNode worldnode = app.World.WorldRoot;
        ISimNode comp1 = app.World.FindComponent("comp1").RootNode;
        ISimNode child1 = app.World.FindComponent("node2").FindNode("child1");

        List<NodeListEntry> entries = new List<NodeListEntry>
        {
            new NodeListEntry(worldnode, NodeEntryScope.Tree, NodeEntryType.Include),
            new NodeListEntry(comp1, NodeEntryScope.Component, NodeEntryType.Exclude),
            new NodeListEntry(child1, NodeEntryScope.Node, NodeEntryType.Exclude)
        };

        var resultNodes = IoC.Get<INodeEntryListHelper>().FilterNodes(entries);

example.code:
        var app = IoC.Get<IApplication>();
        ISimComponent comp1 = app.World.FindComponent("comp1");
        ISimNode rootnode = comp1.RootNode;
        ISimNode subnode1 = comp1.FindNode("subnode1");
        ISimNode subnode2 = comp1.FindNode("subnode2");

        List<NodeListEntry> entries = new List<NodeListEntry>
        {
            new NodeListEntry(rootnode, NodeEntryScope.Component, NodeEntryType.Include),
            new NodeListEntry(subnode1, NodeEntryScope.Node, NodeEntryType.Exclude)
            new NodeListEntry(subnode2, NodeEntryScope.Tree, NodeEntryType.Exclude)
        };

        var resultNodes = IoC.Get<INodeEntryListHelper>().FilterNodes(entries);

