     Creating a path statement:
     
         var robot = IoC.Get<ITeachContext>().ActiveRobot;
         var console = IoC.Get<IConsoleViewModel>();
         var path = robot.Executor.Program.MainRoutine.AddStatement<SchemaPathStatement>();
         var indices = path.AddSchemaProperties
         (
             new Tuple<string, Type, object>[]
             {
                 new Tuple<string, Type, object>("Position", typeof(Matrix), new Matrix()),
                 new Tuple<string, Type, object>("FrameVisibility", typeof(bool), false),
                 new Tuple<string, Type, object>("LineVisibility", typeof(bool), true),
                 new Tuple<string, Type, object>("LineColor", typeof(Vector3), new Vector3()),
                 new Tuple<string, Type, object>("Name", typeof(string), "")
             }
         );

         path.SchemaProperties.GetProperty("FrameVisibility").IsVisible = true;
         path.SchemaProperties.GetProperty("LineVisibility").IsVisible = true;
         path.SchemaProperties.GetProperty("LineColor").IsVisible = true;
         path.SchemaProperties.GetProperty("Name").IsVisible = true;
         path.GetProperty("PositionField").Value = prop_indices[0];
         path.GetProperty("FrameVisibleField").Value = prop_indices[1];
         path.GetProperty("LineVisibleField").Value = prop_indices[2];
         path.GetProperty("LineColorField").Value = prop_indices[3];

         path.BeginBatchUpdate(10);

         var allFrames = path.SchemaPositions.Cast<ISchemaPositionFrame>();
         foreach (var frame in allFrames)
         {
             var matrix = new Matrix();
             matrix.SetP(new Vector3(frame.Index * 50, 0, 0));
             var values = new object[]{ matrix, true, true, new Vector3(0,1,1), "Frame_" + ((ISchemaPositionFrame)frame).Index };
             path.SetSchemaValues(frame.Index, indices, values);
         }

         path.EndBatchUpdate(frame_count);
         console.AppendMessage("Created path statement: " + path.Name);
         IoC.Get<ISelectionManager>().SetSelection(path, false);
         IoC.Get<IRenderService>().RequestRender();

Offsetting path's positions:

    var allFrames = path.SchemaPositions.Cast<ISchemaPositionFrame>();
    foreach (var frame in allFrames)
    {
        var matrix = frame.TransformationInWorld;
        var pos = matrix.GetP();
        pos.Z += 20;
        matrix.SetP(pos);
        frame.TransformationInWorld = matrix;
    }

Offsetting selected positions:

    var selectedFrames = IoC.Get<ISelectionManager>().GetSelection<IPositionFrame>().OfType<ISchemaPositionFrame>();
    var allFrames = selectedFrames.SelectMany(item => item.CombinedItems).Cast<ISchemaPositionFrame>();
    foreach (var frame in allFrames)
    {
        var matrix = frame.TransformationInWorld;
        var pos = matrix.GetP();
        pos.Z += 20;
        matrix.SetP(pos);
        frame.TransformationInWorld = matrix;
    }

Listing position properties:

    var path = IoC.Get<ISelectionManager>().GetSelection<IStatement>().OfType<IPathStatement>().FirstOrDefault();
    var console = IoC.Get<IConsoleViewModel>();
    var props = "";
    foreach (var prop in path.SchemaProperties.Properties)
    {
        props += prop.Name + ", ";
    }
    console.AppendMessage("Schema properties: " + props);

Reading/writing position properties:

    var path = IoC.Get<ISelectionManager>().GetSelection<IStatement>().OfType<IPathStatement>().FirstOrDefault();
    var allFrames = path.SchemaPositions.Cast<ISchemaPositionFrame>();
    foreach (var frame in allFrames)
    {
        var framePath = (IPathStatement)frame.Statement;
        var frameIndex = frame.Index;
        var positionFieldIndex = (int)path.GetProperty("PositionField").Value;
        var position1 = (Matrix)frame.GetSchemaValue("Position");
        var position2 = (Matrix)frame.GetSchemaValue(positionFieldIndex);
        frame.SetSchemaValue("Position", position1);
        frame.SetSchemaValue(positionFieldIndex, position2);
    }

