example.code:
 class LicensedCodeImplementation : IDisposable
 {
     ILicensingService   _licensingService;
     ILicenseHandle      _license;

     public LicensedCodeImplementation([Import] ILicensingService licensingService)
     {
         _licensingService = licensingService;

         // This will throw an exception if there is a problem with the
         // license.
         // NOTE: Challenge-response mechanism is not shown here.
         _license = _licensingService.GetMainLicense("feature", null);
     }

     public void Dispose()
     {
         if(_license != null)
         {
             _license.Dispose();
         }
     }
 }

